// Kiểm mã nhóm trong header x-ma-nhom (hoặc ?ma=), giữ lại body và query
const crypto = require('crypto');
const w = $input.first().json;
const expected = $env.GIA_LAP_MA || '';
const got = String((w.headers || {})['x-ma-nhom'] || (w.query || {}).ma || '');
const h = (s) => crypto.createHash('sha256').update(s).digest();
const ok = !!expected && crypto.timingSafeEqual(h(got), h(expected));
return [{ json: { ok, body: w.body || {}, query: w.query || {} } }];

// Lấy danh sách sản phẩm từ kết quả tool
const r = $input.first().json;
const first = (r.results || [])[0] || {};
return [{ json: { ok: !!first.ok, source: r.source || null, products: first.products || [], loi: first.error || null } }];

