// Kiểm giỏ hàng theo danh sách sản phẩm, tính tổng tiền, dựng sự kiện đơn mới như TikTok
const body = $('dat-don: kiểm mã').first().json.body || {};
const products = (($input.first().json.results || [])[0] || {}).products || [];
const bySku = Object.fromEntries(products.map((p) => [p.sku, p]));
const raw = Array.isArray(body.items) ? body.items : [];
if (!raw.length) return [{ json: { ok: false, loi: 'Giỏ hàng trống: gửi items = [{ sku, quantity }]' } }];
const items = [];
let total = 0;
for (const it of raw) {
  const sku = String(it.sku || '').trim().toUpperCase();
  const qty = Math.max(1, parseInt(it.quantity, 10) || 1);
  const p = bySku[sku];
  if (!p) return [{ json: { ok: false, loi: `Không có sản phẩm ${sku}` } }];
  if (p.stock < qty) return [{ json: { ok: false, loi: `${p.name} chỉ còn ${p.stock}` } }];
  items.push({ seller_sku: sku, quantity: qty });
  total += p.price * qty;
}
const orderId = '5799' + String(Date.now()).slice(-12) + String(Math.floor(Math.random() * 100)).padStart(2, '0');
const ts = Math.floor(Date.now() / 1000);
const event = { type: 1, tts_notification_id: 'gialap' + Date.now(), shop_id: 'gia-lap-shop', timestamp: ts,
  data: { order_id: orderId, order_status: 'AWAITING_SHIPMENT', is_on_hold_order: false, update_time: ts } };
return [{ json: { ok: true, viec: 'dat_don', order_id: orderId, status: 'AWAITING_SHIPMENT', items: JSON.stringify(items),
  total, buyer_user_id: String(body.buyer_user_id || 'gia-lap-khach'), event } }];

// Ký sự kiện như TikTok rồi gửi vào Router, hoặc báo đóng gói vào Đặt vận chuyển như Odoo
const crypto = require('crypto');
const ODOO = { url: ($env.ODOO_URL || 'http://odoo:8069') + '/jsonrpc', db: $env.ODOO_DB || 'hdx',
  login: $env.ODOO_N8N_LOGIN || 'n8n', pw: $env.ODOO_N8N_PASSWORD || '' };
// Gọi JSON-RPC của Odoo, ném lỗi kèm thông báo của Odoo
const rpc = async (service, method, args) => {
  const r = await this.helpers.httpRequest({ method: 'POST', url: ODOO.url, json: true, timeout: 30000,
    body: { jsonrpc: '2.0', method: 'call', params: { service, method, args } } });
  if (r.error) throw new Error(`Odoo: ${(r.error.data && r.error.data.message) || r.error.message}`);
  return r.result;
};
// Gọi một method của model Odoo
const call = async (model, method, args, kw = {}) => {
  const uid = await rpc('common', 'login', [ODOO.db, ODOO.login, ODOO.pw]);
  if (!uid) throw new Error('Odoo: sai ODOO_N8N_LOGIN hoặc ODOO_N8N_PASSWORD');
  return rpc('object', 'execute_kw', [ODOO.db, uid, ODOO.pw, model, method, args, kw]);
};
// Xác nhận (Validate) phiếu xuất kho của đơn trong Odoo; Automation Rule của Odoo sẽ báo n8n đặt vận chuyển
const validateOdoo = async (orderId) => {
  if (!ODOO.pw) return null;
  const so = (await call('sale.order', 'search_read', [[['client_order_ref', '=', orderId]]], { fields: ['picking_ids'], limit: 1 }))[0];
  if (!so || !so.picking_ids.length) return null;
  const picks = await call('stock.picking', 'read', [so.picking_ids], { fields: ['name', 'state', 'picking_type_code'] });
  const out = picks.find((p) => p.picking_type_code === 'outgoing' && !['done', 'cancel'].includes(p.state));
  if (!out) return picks.find((p) => p.picking_type_code === 'outgoing' && p.state === 'done') || null;
  await call('stock.picking', 'button_validate', [[out.id]]);
  const after = (await call('stock.picking', 'read', [[out.id]], { fields: ['name', 'state'] }))[0];
  if (after.state !== 'done') throw new Error(`Phiếu ${after.name} chưa xong (trạng thái ${after.state})`);
  return after;
};
const s = $('dat-don: tính đơn').first().json;
const row = $input.first().json;
if (!row.order_id) return [{ json: { ok: false, loi: `Không có đơn ${s.order_id}` } }];
let res;
let odooPicking = null;
if (s.viec === 'dong_goi') {
  try { odooPicking = await validateOdoo(s.order_id); } catch (e) { odooPicking = { loi: e.message }; }
}
if (s.viec === 'dong_goi' && odooPicking && odooPicking.name) {
  res = { statusCode: 200, body: { ok: true, odoo_picking: odooPicking.name } };
} else if (s.viec === 'dong_goi') {
  const body = { _model: 'stock.picking', id: 0, name: `WH/OUT/GL${s.order_id.slice(-5)}`, origin: 'GIA-LAP',
    state: 'done', picking_type_code: 'outgoing', client_order_ref: s.order_id };
  res = await this.helpers.httpRequest({
    method: 'POST', url: `http://localhost:5678/webhook/odoo-picking-done?secret=${encodeURIComponent($env.ODOO_WEBHOOK_SECRET || '')}`,
    json: true, body, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000,
  });
} else {
  const raw = JSON.stringify(s.event);
  const sig = crypto.createHmac('sha256', $env.TIKTOK_APP_SECRET || '').update($env.TIKTOK_APP_KEY || '').update(raw).digest('hex');
  res = await this.helpers.httpRequest({
    method: 'POST', url: 'http://localhost:5678/webhook/tiktok-events',
    headers: { 'Content-Type': 'application/json', Authorization: sig },
    body: raw, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000,
  });
}
const ok = res.statusCode >= 200 && res.statusCode < 300;
return [{ json: { ok, order_id: s.order_id, viec: s.viec, status: row.status, total: s.total ?? null,
  loi: ok ? null : `Hệ thống trả lỗi ${res.statusCode}` } }];

