if (viec === 'dang_giao' || viec === 'da_giao') {
  event = { type: 1, ...base, data: { order_id: orderId, order_status: STATUS[viec], is_on_hold_order: false, update_time: ts } };
} else if (viec === 'huy_don') {
  event = { type: 11, ...base, data: { order_id: orderId, cancellations_role: 'BUYER', cancel_status: 'CANCELLATION_REQUEST_COMPLETE', update_time: ts } };
}
return [{ json: { ok: true, viec, order_id: orderId, status: STATUS[viec], items: '[]', total: 0, buyer_user_id: '', event } }];

