SELECT COALESCE(json_agg(t ORDER BY t.id DESC), '[]'::json) AS messages FROM (
  SELECT id, conversation_id, noi_dung, gui_luc FROM gia_lap_tin_nhan ORDER BY id DESC LIMIT 50
) t;

